(736874, 79015, 15920, '<td valign="top">I hope you get the score you are trying to achieve, this is a little different than I expected to see in this competition.</td>', 'I hope you get the score you are trying to achieve, this is a little different than I expected to see in this competition.', '2004-05-26 09:08:40.000000', NULL, 1),
(736876, 79128, 20407, '<td valign="top">Very nice, I like the colours &amp; balance.</td>', 'Very nice, I like the colours & balance.', '2004-05-26 09:09:11.000000', NULL, 1),
(736877, 79306, 20407, '<td valign="top">I like the colours in this a lot.</td>', 'I like the colours in this a lot.', '2004-05-26 09:09:24.000000', NULL, 1),
(736878, 77789, 15920, '<td valign="top">This would have been better if the cat was looking at you.  I also can''t tell if there is fill flash or not in this picture.</td>', 'This would have been better if the cat was looking at you.  I also can''t tell if there is fill flash or not in this picture.', '2004-05-26 09:10:18.000000', NULL, 1),
