(738938, 78090, 7684, '<td valign="top">7.</td>', '7.', '2004-05-27 08:28:20.000000', NULL, 1),
(738964, 78369, 16970, '<td valign="top">Multiple lights?  A bit soft for my liking...  Dramatic... DOF problem...  Highlights are burnt out...  A bit dark...  More light would have been better...  Under exposed... Would have been better in B&amp;W.  <br/> <br/>All kidding aside this is a great pic...  Dramatic and clever use of the multiple lights.   Good use of DOF the eye is drawn to the eye of the subject with great effect.  Well done.  (10)</td>', 'Multiple lights?  A bit soft for my liking...  Dramatic... DOF problem...  Highlights are burnt out...  A bit dark...  More light would have been better...  Under exposed... Would have been better in B&W.   All kidding aside this is a great pic...  Dramatic and clever use of the multiple lights.   Good use of DOF the eye is drawn to the eye of the subject with great effect.  Well done.  (10)', '2004-05-27 09:05:45.000000', NULL, 1),
(738967, 78699, 6999, '<td valign="top">Like the composition, though I''m not such a fan of the grain of the shot. I also think that missing the brightest area of the tines with you chosen dof might be a mistake - it leaves a conflict between the natural draw of the brightness and the opposing draw o the focus that doesn''t allow the eye to settle at all. But there''s a feel I like here very much.</td>', 'Like the composition, though I''m not such a fan of the grain of the shot. I also think that missing the brightest area of the tines with you chosen dof might be a mistake - it leaves a conflict between the natural draw of the brightness and the opposing draw o the focus that doesn''t allow the eye to settle at all. But there''s a feel I like here very much.', '2004-05-27 09:06:06.000000', NULL, 1),
(738970, 79314, 21594, '<td valign="top">very original...i''m glad that somebody turned those light sources off...:-)<br/> <br/>the white balance is not very good here and unfortunately th ecandle is tilted clockwise...8<br/> <br/>good effort overall with an perticular aproach...</td>', 'very original...i''m glad that somebody turned those light sources off...:-) the white balance is not very good here and unfortunately th ecandle is tilted clockwise...8 good effort overall with an perticular aproach...', '2004-05-27 09:08:31.000000', NULL, 1),
(738973, 79163, 21594, '<td valign="top">interesting but what id disturbing here in my oppinion are the black triangles of the left and right...i would have avoided it...6</td>', 'interesting but what id disturbing here in my oppinion are the black triangles of the left and right...i would have avoided it...6', '2004-05-27 09:11:13.000000', NULL, 1),
(738974, 78325, 21594, '<td valign="top">good lighting, unfortunately the focus is only on the right side of the photo...</td>', 'good lighting, unfortunately the focus is only on the right side of the photo...', '2004-05-27 09:12:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(738980, 78985, 21594, '<td valign="top">very good...one of my favourites for this challange...unfortunately you haven''t made a very good use of the cristal ball and its transparency...</td>', 'very good...one of my favourites for this challange...unfortunately you haven''t made a very good use of the cristal ball and its transparency...', '2004-05-27 09:13:47.000000', NULL, 1),
(738982, 79131, 21594, '<td valign="top">nice ideea...i''m not sure if this is the best composition but overall good effort</td>', 'nice ideea...i''m not sure if this is the best composition but overall good effort', '2004-05-27 09:17:35.000000', NULL, 1),
(738991, 79296, 7015, '<td valign="top">Thiscould have really been great, but it''s a little out of focus on my screen and I would have composed it a little more differently. Something more elemental .</td>', 'Thiscould have really been great, but it''s a little out of focus on my screen and I would have composed it a little more differently. Something more elemental .', '2004-05-27 09:23:38.000000', NULL, 1),
(738997, 79099, 7015, '<td valign="top">Is this the canal in Indy? It seems a little soft in focus, but it''s a good idea. How about getting a little human interest with a silhouette of a couple people walking into the frame on the top right. With a tripod and a slower exposure time you could have really saturated the colors more.</td>', 'Is this the canal in Indy? It seems a little soft in focus, but it''s a good idea. How about getting a little human interest with a silhouette of a couple people walking into the frame on the top right. With a tripod and a slower exposure time you could have really saturated the colors more.', '2004-05-27 09:26:37.000000', NULL, 1),
(738998, 79221, 7015, '<td valign="top">My wife says to give it a  10, for some reason I hesitate, but marital bliss.... Good job.</td>', 'My wife says to give it a  10, for some reason I hesitate, but marital bliss.... Good job.', '2004-05-27 09:27:52.000000', NULL, 1),
(738999, 79034, 21594, '<td valign="top">very good ideea...one of my favourites...the scratches on th ebulb...i would weather clone them out or try to accentuate the image of a old dusted and scratched film...cheers</td>', 'very good ideea...one of my favourites...the scratches on th ebulb...i would weather clone them out or try to accentuate the image of a old dusted and scratched film...cheers', '2004-05-27 09:28:35.000000', NULL, 1),
(739003, 79128, 7015, '<td valign="top">My wife and I both agree, this is cool. Good job!</td>', 'My wife and I both agree, this is cool. Good job!', '2004-05-27 09:30:16.000000', NULL, 1),
(739032, 78309, 7015, '<td valign="top">Great location, but you need more of a subject, imagine a silhouetted person walking up the left side of the stairs, talk about a layered image. Good job!</td>', 'Great location, but you need more of a subject, imagine a silhouetted person walking up the left side of the stairs, talk about a layered image. Good job!', '2004-05-27 10:07:44.000000', NULL, 1),
(739049, 79195, 19841, '<td valign="top">Your aluminum foil cookie casts a lovely light on the flowesr, but I think I would like the picture better with it cropped out.   The sharp contrast on the foil upstages the soft moodiness of the flowers.  7</td>', 'Your aluminum foil cookie casts a lovely light on the flowesr, but I think I would like the picture better with it cropped out.   The sharp contrast on the foil upstages the soft moodiness of the flowers.  7', '2004-05-27 10:22:29.000000', NULL, 1),
(739053, 78403, 19841, '<td valign="top">Well spotted!  Few people look up, and they miss things like this.   The bluish light from the windows sets off the warm artificial light nicely.</td>', 'Well spotted!  Few people look up, and they miss things like this.   The bluish light from the windows sets off the warm artificial light nicely.', '2004-05-27 10:25:34.000000', NULL, 1),
(739062, 78034, 19841, '<td valign="top">That must have been very tricky to set up!   Nicely done.</td>', 'That must have been very tricky to set up!   Nicely done.', '2004-05-27 10:31:26.000000', NULL, 1),
(739083, 79314, 19841, '<td valign="top">For some reason the tilt to the candle really bothers me.  I think I would like this photo better straightened up.  Nice interpretation of the challenge!</td>', 'For some reason the tilt to the candle really bothers me.  I think I would like this photo better straightened up.  Nice interpretation of the challenge!', '2004-05-27 10:41:10.000000', NULL, 1),
(739089, 78330, 19841, '<td valign="top">Oooo, pretty!</td>', 'Oooo, pretty!', '2004-05-27 10:47:43.000000', NULL, 1),
(739093, 79306, 19952, '<td valign="top">Beautiful shot! I love the colors and the excellent clarity in the tree. Great job.</td>', 'Beautiful shot! I love the colors and the excellent clarity in the tree. Great job.', '2004-05-27 10:50:48.000000', NULL, 1),
(739100, 79041, 19952, '<td valign="top">Really beautiful shot with great colors and clarity. One of my favorites of this challenge. Is that your face in the top left of the bulb? ;-)</td>', 'Really beautiful shot with great colors and clarity. One of my favorites of this challenge. Is that your face in the top left of the bulb? ;-)', '2004-05-27 10:57:32.000000', NULL, 1),
(739101, 77996, 19841, '<td valign="top">I can''t tell what the marble is sitting on, but it does make a nice abstract image.</td>', 'I can''t tell what the marble is sitting on, but it does make a nice abstract image.', '2004-05-27 10:59:49.000000', NULL, 1),
(739104, 77985, 19841, '<td valign="top">He looks like a used soul dealer.  Nice.</td>', 'He looks like a used soul dealer.  Nice.', '2004-05-27 11:02:27.000000', NULL, 1),
(739105, 79300, 19952, '<td valign="top">Without the grain and what appears to be some over-sharpening, this would have been a really great shot. Even with that, you managed to create a dramatic image with some great colors. I hope you experiment with this shot some more. Good job!</td>', 'Without the grain and what appears to be some over-sharpening, this would have been a really great shot. Even with that, you managed to create a dramatic image with some great colors. I hope you experiment with this shot some more. Good job!', '2004-05-27 11:03:06.000000', NULL, 1),
(739110, 78114, 19952, '<td valign="top">I am just in awe of what you were able to accomplish in this photograph. Really great job.</td>', 'I am just in awe of what you were able to accomplish in this photograph. Really great job.', '2004-05-27 11:07:23.000000', NULL, 1),
(739112, 79131, 20494, '<td valign="top">cool! didn''t knoe my Panasonic GD88 could do that ;P</td>', 'cool! didn''t knoe my Panasonic GD88 could do that ;P', '2004-05-27 11:09:24.000000', NULL, 1),
(739113, 78277, 19952, '<td valign="top">For such a simple shot, this turned out really well. You captured some excellent color and clarity and did a great job with composition. Nice shot.</td>', 'For such a simple shot, this turned out really well. You captured some excellent color and clarity and did a great job with composition. Nice shot.', '2004-05-27 11:09:31.000000', NULL, 1),
(739116, 79131, 19952, '<td valign="top">Nice clear photo with almost no grain, which is a real accomplishment with the light you used. The red lines are a bit haphazard and jerky at points, but this is one of the best ideas and executions I''ve seen for this contest. Great job.</td>', 'Nice clear photo with almost no grain, which is a real accomplishment with the light you used. The red lines are a bit haphazard and jerky at points, but this is one of the best ideas and executions I''ve seen for this contest. Great job.', '2004-05-27 11:12:26.000000', NULL, 1),
(739123, 78212, 19952, '<td valign="top">Nice, subtle entry for this challenge and a beautiful image. I do wish the tarp in the BG were not so wrinkled for this particular shot, but it came out great regardless. Nice job!</td>', 'Nice, subtle entry for this challenge and a beautiful image. I do wish the tarp in the BG were not so wrinkled for this particular shot, but it came out great regardless. Nice job!', '2004-05-27 11:17:22.000000', NULL, 1),
(739126, 79307, 15919, '<td valign="top">The subject is pretty cool.  Think its litle overexposed and lacks more contrast.  Also it dont seems very sharp.</td>', 'The subject is pretty cool.  Think its litle overexposed and lacks more contrast.  Also it dont seems very sharp.', '2004-05-27 11:17:28.000000', NULL, 1),
(739130, 78502, 15919, '<td valign="top">Cool subject but the image lacks sharpness.  Maybe a tripod would have come in hand in your sitation.</td>', 'Cool subject but the image lacks sharpness.  Maybe a tripod would have come in hand in your sitation.', '2004-05-27 11:18:22.000000', NULL, 1),
(739131, 78212, 15919, '<td valign="top">Good lightning and cool background.  Dont know how well it meets the challenge unless you are talking about light in indirect meaning (which of course is fine).</td>', 'Good lightning and cool background.  Dont know how well it meets the challenge unless you are talking about light in indirect meaning (which of course is fine).', '2004-05-27 11:19:52.000000', NULL, 1),
(739133, 78512, 15919, '<td valign="top">This one is pretty strange and hard to understand.  You seem to be getting some cool effect there but I´m not sure it has turned out as good as it could be.</td>', 'This one is pretty strange and hard to understand.  You seem to be getting some cool effect there but I´m not sure it has turned out as good as it could be.', '2004-05-27 11:21:09.000000', NULL, 1),
(739134, 77845, 19952, '<td valign="top">Sorry, but this has nothing to do with this challenge. Cute title, though.</td>', 'Sorry, but this has nothing to do with this challenge. Cute title, though.', '2004-05-27 11:21:49.000000', NULL, 1),
(739135, 79211, 15919, '<td valign="top">blue isn´t very obvious unless the blue light spots on the tomatoes.  Think you should have used a longer exposure and maybe shoot it in closer angel or at least give it a tighter croping to leave out most of the bowl.</td>', 'blue isn´t very obvious unless the blue light spots on the tomatoes.  Think you should have used a longer exposure and maybe shoot it in closer angel or at least give it a tighter croping to leave out most of the bowl.', '2004-05-27 11:23:19.000000', NULL, 1),
(739137, 78222, 19952, '<td valign="top">As far as photos of dead birds go, this is a pretty nice one. I just can''t imagine what it has to do with this challenge, though.</td>', 'As far as photos of dead birds go, this is a pretty nice one. I just can''t imagine what it has to do with this challenge, though.', '2004-05-27 11:24:26.000000', NULL, 1),
(739139, 79237, 19952, '<td valign="top">Yes, it is delicately beautiful, but there seems to be only one source of light. Nice photo, though.</td>', 'Yes, it is delicately beautiful, but there seems to be only one source of light. Nice photo, though.', '2004-05-27 11:25:40.000000', NULL, 1),
(739146, 78222, 327, '<td valign="top">Maybe this is over my head but I don''t see ''lights'' here, not sure what your trying to say.  The composition is okay but it''s oof. Sorry just not a shot that will appel to many. Good luck with it.</td>', 'Maybe this is over my head but I don''t see ''lights'' here, not sure what your trying to say.  The composition is okay but it''s oof. Sorry just not a shot that will appel to many. Good luck with it.', '2004-05-27 11:33:44.000000', NULL, 1),
(739149, 79154, 327, '<td valign="top">?-Maybe if this wasn''t so centered. I''d suggest adding a little saturation to make the colors rich. They look a bit washed out. I have seen orchids this color, pretty.</td>', '?-Maybe if this wasn''t so centered. I''d suggest adding a little saturation to make the colors rich. They look a bit washed out. I have seen orchids this color, pretty.', '2004-05-27 11:35:40.000000', NULL, 1),
(739152, 77844, 327, '<td valign="top">Okay..for me blue and yellow always works! Here I suggest that you crop off that bottom 1/4 inch of table, it''s over exposed and not adding to the shot, it draws the eye away. Also the shot is maybe a bit low on the pot.....I realize that is the main subject for this shot, but we''d of seen the vivid colors. Finally the white in the upper right is a not good....it''s washing out the amazing violets that you''ve grown!! Wow you have a green thumb. I have one but it''s so small, not lush like yours.. :)</td>', 'Okay..for me blue and yellow always works! Here I suggest that you crop off that bottom 1/4 inch of table, it''s over exposed and not adding to the shot, it draws the eye away. Also the shot is maybe a bit low on the pot.....I realize that is the main subject for this shot, but we''d of seen the vivid colors. Finally the white in the upper right is a not good....it''s washing out the amazing violets that you''ve grown!! Wow you have a green thumb. I have one but it''s so small, not lush like yours.. :)', '2004-05-27 11:39:07.000000', NULL, 1),
(739155, 77789, 327, '<td valign="top">I like the sunshine, and the pose. The background is just a bit distracting.</td>', 'I like the sunshine, and the pose. The background is just a bit distracting.', '2004-05-27 11:39:46.000000', NULL, 1),
(739176, 79299, 6130, '<td valign="top">Nice and good.</td>', 'Nice and good.', '2004-05-27 12:05:09.000000', NULL, 1),
(739179, 79306, 20941, '<td valign="top">this is stunning!</td>', 'this is stunning!', '2004-05-27 12:08:44.000000', NULL, 1),
(739181, 78882, 22199, '<td valign="top">GREAT mental application to the challenge.</td>', 'GREAT mental application to the challenge.', '2004-05-27 12:10:13.000000', NULL, 1),
(739185, 79262, 1570, '<td valign="top">this is simply spectacular, so pretty and clever! 10.</td>', 'this is simply spectacular, so pretty and clever! 10.', '2004-05-27 12:13:58.000000', NULL, 1),
(739186, 79033, 16106, '<td valign="top">Well done in so many ways, except the way it responds to the challenge. I particularly like the framing. I just wish that there was some evidence of a light source other than the sun.</td>', 'Well done in so many ways, except the way it responds to the challenge. I particularly like the framing. I just wish that there was some evidence of a light source other than the sun.', '2004-05-27 12:14:54.000000', NULL, 1),
(739192, 79291, 19708, '<td valign="top">I don''t see multiple sources of light on this.<br/>--- updated ---<br/>A second look shows no way could the lower portion of the light fixture be visible had it not been for other light sources.</td>', 'I don''t see multiple sources of light on this.--- updated ---A second look shows no way could the lower portion of the light fixture be visible had it not been for other light sources.', '2004-05-27 12:22:44.000000', NULL, 1),
(739195, 79237, 19708, '<td valign="top">After looking closer, sunlight &amp; flash are noted. (reflection on lower leaves vs. shadow under butterfly). Initial impression was just a flash....<br/>Nice shot! (I love Butterflies)<br/></td>', 'After looking closer, sunlight & flash are noted. (reflection on lower leaves vs. shadow under butterfly). Initial impression was just a flash....Nice shot! (I love Butterflies)', '2004-05-27 12:27:25.000000', NULL, 1),
(739228, 79191, 22041, '<td valign="top">Very good shot, I think if it had been just a little bit lighter it would have more impact.</td>', 'Very good shot, I think if it had been just a little bit lighter it would have more impact.', '2004-05-27 12:56:11.000000', NULL, 1),
(739229, 79290, 22041, '<td valign="top">Great shot, love the look on this guy''s face!</td>', 'Great shot, love the look on this guy''s face!', '2004-05-27 12:57:17.000000', NULL, 1),
(739232, 79176, 22041, '<td valign="top">Great idea, but I would have like it to come out a little less grainy.</td>', 'Great idea, but I would have like it to come out a little less grainy.', '2004-05-27 12:58:22.000000', NULL, 1),
(739234, 78251, 22041, '<td valign="top">Great time lapse and everything is in terrific focus</td>', 'Great time lapse and everything is in terrific focus', '2004-05-27 12:59:14.000000', NULL, 1),
