(740795, 78533, 9763, '<td valign="top">Beautiful sunrise, nice silhouette and composition.  Cropping tight on the right.  Where''s the multiple light sources?  I see the sun as 1.  Did you use your flash at all or something?</td>', 'Beautiful sunrise, nice silhouette and composition.  Cropping tight on the right.  Where''s the multiple light sources?  I see the sun as 1.  Did you use your flash at all or something?', '2004-05-28 14:15:47.000000', NULL, 1),
(740816, 78306, 5364, '<td valign="top">A slightly lower angle might have made the lights a bit more prominent and therefore a better fit to the challenge, but a good picture.</td>', 'A slightly lower angle might have made the lights a bit more prominent and therefore a better fit to the challenge, but a good picture.', '2004-05-28 14:33:11.000000', NULL, 1),
(740829, 79281, 9690, '<td valign="top">I think this is an excellent shot.  Great for this challenge.  I love the fact that there is seperate lighting (different type too) for the musician and the audience who is completely under his spell.  Very good work.</td>', 'I think this is an excellent shot.  Great for this challenge.  I love the fact that there is seperate lighting (different type too) for the musician and the audience who is completely under his spell.  Very good work.', '2004-05-28 14:41:32.000000', NULL, 1),
