(740876, 78386, 22332, '<td valign="top">Wow!  Nice!  I think the only way to improve on this would be to make the front light a bit softer.  Great shot!</td>', 'Wow!  Nice!  I think the only way to improve on this would be to make the front light a bit softer.  Great shot!', '2004-05-28 15:23:00.000000', NULL, 1),
(740878, 79294, 22332, '<td valign="top">Very interesting!  How is that lit?</td>', 'Very interesting!  How is that lit?', '2004-05-28 15:24:14.000000', NULL, 1),
(740880, 78046, 18374, '<td valign="top">Very nice!  I think this is an excellent use of B&amp;W.  The exposure is very good- not too dark and not too light.  I like it.</td>', 'Very nice!  I think this is an excellent use of B&W.  The exposure is very good- not too dark and not too light.  I like it.', '2004-05-28 15:24:23.000000', NULL, 1),
(740881, 79020, 16004, '<td valign="top">where in the name of all that is holy did you find a set of traffic lights?  i''m deeply impressed!  i''m intrigued to know why you decided to focus the light on pool balls though - i can''t help but think an opportunity was slightly missed by not having something longish and metallic.  i''m deeply impressed with the set-up though.  a bit of even spread with the focus might help (the balls at the front appear fuzzy); as would moving the camera to the right a bit, or using a sheet of glossy white card off camera to the left reflecting the light sources, all so we can see the balls lit up (all we see is the shadows and the light on the sheet).  interesting shot that looked quite fun to do.  5.</td>', 'where in the name of all that is holy did you find a set of traffic lights?  i''m deeply impressed!  i''m intrigued to know why you decided to focus the light on pool balls though - i can''t help but think an opportunity was slightly missed by not having something longish and metallic.  i''m deeply impressed with the set-up though.  a bit of even spread with the focus might help (the balls at the front appear fuzzy); as would moving the camera to the right a bit, or using a sheet of glossy white card off camera to the left reflecting the light sources, all so we can see the balls lit up (all we see is the shadows and the light on the sheet).  interesting shot that looked quite fun to do.  5.', '2004-05-28 15:24:33.000000', NULL, 1),
(740883, 78339, 22332, '<td valign="top">Nice and simple but interesting at the same time.</td>', 'Nice and simple but interesting at the same time.', '2004-05-28 15:24:59.000000', NULL, 1),
(740884, 78212, 20023, '<td valign="top">A little on the dark side.  Would like to see more detail.  Too much black in the upper left corner.  Otherwise, well done.</td>', 'A little on the dark side.  Would like to see more detail.  Too much black in the upper left corner.  Otherwise, well done.', '2004-05-28 15:25:41.000000', NULL, 1),
(740885, 78488, 22332, '<td valign="top">It seems to be a bit blury.  The black at the bottom could have been cropped, too.</td>', 'It seems to be a bit blury.  The black at the bottom could have been cropped, too.', '2004-05-28 15:25:55.000000', NULL, 1),
(740887, 78275, 20023, '<td valign="top">Impressive</td>', 'Impressive', '2004-05-28 15:26:18.000000', NULL, 1),
(740889, 79309, 22332, '<td valign="top">I hate powerlines; they always get in the way!  It would have been a 10!  Exelect shot.</td>', 'I hate powerlines; they always get in the way!  It would have been a 10!  Exelect shot.', '2004-05-28 15:27:25.000000', NULL, 1),
(740890, 79299, 20023, '<td valign="top">Excellent color contrast!  Ordinarily I wouldn''t think this a very interesting photo, but in the context of the contest, definitely superb!</td>', 'Excellent color contrast!  Ordinarily I wouldn''t think this a very interesting photo, but in the context of the contest, definitely superb!', '2004-05-28 15:27:36.000000', NULL, 1),
(740891, 79016, 20023, '<td valign="top">very busy, but cool reflection.</td>', 'very busy, but cool reflection.', '2004-05-28 15:28:17.000000', NULL, 1),
(740892, 79143, 22332, '<td valign="top">Nice! the two bright, star-shaped light are a bit distracting, though.</td>', 'Nice! the two bright, star-shaped light are a bit distracting, though.', '2004-05-28 15:28:17.000000', NULL, 1),
(740893, 78303, 20023, '<td valign="top">well done, but centering the vase and leveling the camera would have helped temendously.</td>', 'well done, but centering the vase and leveling the camera would have helped temendously.', '2004-05-28 15:28:56.000000', NULL, 1),
(740894, 79122, 22332, '<td valign="top">Cool angle, one light source.  I do like it though!</td>', 'Cool angle, one light source.  I do like it though!', '2004-05-28 15:29:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(740895, 78407, 20023, '<td valign="top">where are the other light sources?</td>', 'where are the other light sources?', '2004-05-28 15:29:59.000000', NULL, 1),
(740896, 78810, 22332, '<td valign="top">Arg, its tipped!  Very nice, anyway!</td>', 'Arg, its tipped!  Very nice, anyway!', '2004-05-28 15:30:05.000000', NULL, 1),
(740897, 79160, 16004, '<td valign="top">good choice - i was trying very hard to find something that might reflect light in an interesting manner...  however, to achieve a great score, blurriness and a soft focus is a bit of a disadvantage.  was this taken with the camera in your hands?  if so, may i recommend putting the camera down, maybe on a pile of books or cds (or get a mini 6 inch tri-pod for like 20 bucks / 10 quid) and using the timer built in the camera.  no shake, and perfect focus will be yours.  the brightness could also be toned down a bit - try playing with the brightness and contrast on whatever software you have.  compostion though is really good, and the choice of colours works well - the red background is lovely.</td>', 'good choice - i was trying very hard to find something that might reflect light in an interesting manner...  however, to achieve a great score, blurriness and a soft focus is a bit of a disadvantage.  was this taken with the camera in your hands?  if so, may i recommend putting the camera down, maybe on a pile of books or cds (or get a mini 6 inch tri-pod for like 20 bucks / 10 quid) and using the timer built in the camera.  no shake, and perfect focus will be yours.  the brightness could also be toned down a bit - try playing with the brightness and contrast on whatever software you have.  compostion though is really good, and the choice of colours works well - the red background is lovely.', '2004-05-28 15:30:06.000000', NULL, 1),
(740898, 79301, 18374, '<td valign="top">Very nice shot!  The waterfall is spectacular.  The light and shadows make this photo really interesting.  My only complaint is that the bottom of the picture is kind of dull- there is a lot of sidewalk in it.</td>', 'Very nice shot!  The waterfall is spectacular.  The light and shadows make this photo really interesting.  My only complaint is that the bottom of the picture is kind of dull- there is a lot of sidewalk in it.', '2004-05-28 15:30:56.000000', NULL, 1),
(740900, 79211, 20023, '<td valign="top">nice use of different colors, but more light would have served better</td>', 'nice use of different colors, but more light would have served better', '2004-05-28 15:31:32.000000', NULL, 1),
(740901, 79296, 20023, '<td valign="top">why so much black around the edges, why not shoot closer to the subject?</td>', 'why so much black around the edges, why not shoot closer to the subject?', '2004-05-28 15:32:03.000000', NULL, 1),
(740903, 78512, 18374, '<td valign="top">Very nice shot!  (This could also work for the 3''s challenge)  I love the arrangement and the shadows on the eggs.</td>', 'Very nice shot!  (This could also work for the 3''s challenge)  I love the arrangement and the shadows on the eggs.', '2004-05-28 15:33:59.000000', NULL, 1),
(740904, 78699, 16004, '<td valign="top">can''t decide if this has the best or worst title ever.  still, i''m not judging the title, it''s the photo that''s important.  actually, no, scrub that, the title is brilliant because it LOOKS like your picture.  the use of multiple sources of light isn''t really that obvious here, unfortunately.  but i like your use of focus.  it could also do with a bit of grain reduction (neatimage which is freeware is good).  6.</td>', 'can''t decide if this has the best or worst title ever.  still, i''m not judging the title, it''s the photo that''s important.  actually, no, scrub that, the title is brilliant because it LOOKS like your picture.  the use of multiple sources of light isn''t really that obvious here, unfortunately.  but i like your use of focus.  it could also do with a bit of grain reduction (neatimage which is freeware is good).  6.', '2004-05-28 15:34:12.000000', NULL, 1),
(740905, 79187, 20023, '<td valign="top">I see only one dominant light source...</td>', 'I see only one dominant light source...', '2004-05-28 15:35:32.000000', NULL, 1),
(740906, 79314, 20023, '<td valign="top">creative interpretation of the challenge</td>', 'creative interpretation of the challenge', '2004-05-28 15:36:03.000000', NULL, 1),
(740908, 79034, 18374, '<td valign="top">Very nice shot.  I''m curious to know your setup on this one- in particular how you got the "halo" around the bulb.</td>', 'Very nice shot.  I''m curious to know your setup on this one- in particular how you got the "halo" around the bulb.', '2004-05-28 15:40:32.000000', NULL, 1),
(740909, 79293, 16004, '<td valign="top">this is a lovely shot.  i''m not enTIRELY sure about the choice of lurid green, but it''s all been captured very wall.  it''s a pity you''re not allowed to clone out the dust spots though - i bet you were itching to get rid of them!  i like the off-centre setting, makes it more interesting.  6.</td>', 'this is a lovely shot.  i''m not enTIRELY sure about the choice of lurid green, but it''s all been captured very wall.  it''s a pity you''re not allowed to clone out the dust spots though - i bet you were itching to get rid of them!  i like the off-centre setting, makes it more interesting.  6.', '2004-05-28 15:42:00.000000', NULL, 1),
(740910, 78464, 18374, '<td valign="top">Great shot!  I like the choice of zooming in to focus on just a small section of the instrument.  The lighting is very nice as well.  Excellent work.</td>', 'Great shot!  I like the choice of zooming in to focus on just a small section of the instrument.  The lighting is very nice as well.  Excellent work.', '2004-05-28 15:42:59.000000', NULL, 1),
(740912, 79319, 18374, '<td valign="top">Nice job with the lighitng.  I like this shot- simple yet interesting.  Well done!</td>', 'Nice job with the lighitng.  I like this shot- simple yet interesting.  Well done!', '2004-05-28 15:44:20.000000', NULL, 1),
(740914, 78297, 18374, '<td valign="top">Excellent shot.  I like the detail and contrasts in this one.</td>', 'Excellent shot.  I like the detail and contrasts in this one.', '2004-05-28 15:46:51.000000', NULL, 1),
(740916, 79176, 16004, '<td valign="top">oh, lot''s of noise.  download the freeware version of neatimage, it''ll minimise the grainy pixellated effects you''ve got.  it''s a pity because the spread of light in the lower corner is quite dramatic.</td>', 'oh, lot''s of noise.  download the freeware version of neatimage, it''ll minimise the grainy pixellated effects you''ve got.  it''s a pity because the spread of light in the lower corner is quite dramatic.', '2004-05-28 15:47:52.000000', NULL, 1),
(740918, 79294, 18374, '<td valign="top">Great shot!  I love the color in this.  I''m curious to know how you set this up.</td>', 'Great shot!  I love the color in this.  I''m curious to know how you set this up.', '2004-05-28 15:51:51.000000', NULL, 1),
(740920, 78823, 18374, '<td valign="top">I don''t know what this is, but it makes for a pretty neat picture!  Is your title a hint? It looks kind of like bearings of some sort.  Nicely done.</td>', 'I don''t know what this is, but it makes for a pretty neat picture!  Is your title a hint? It looks kind of like bearings of some sort.  Nicely done.', '2004-05-28 15:56:12.000000', NULL, 1),
(740924, 79219, 18374, '<td valign="top">Nice picture.  Great lighting and detail.  I''m not a fan of the water drop, though.  I think it detracts from the simplicity aspect of this shot some.  Still, I like it!</td>', 'Nice picture.  Great lighting and detail.  I''m not a fan of the water drop, though.  I think it detracts from the simplicity aspect of this shot some.  Still, I like it!', '2004-05-28 15:59:10.000000', NULL, 1),
