(740926, 78810, 18374, '<td valign="top">Excellent night shot!  I like the colors and the soft foreground.  The light reflections in the water are a nice touch.</td>', 'Excellent night shot!  I like the colors and the soft foreground.  The light reflections in the water are a nice touch.', '2004-05-28 16:01:07.000000', NULL, 1),
(740927, 78309, 22332, '<td valign="top">Good picture, but it really seems to be lacking something.  Hmm...  maybe its the Water Watcher?</td>', 'Good picture, but it really seems to be lacking something.  Hmm...  maybe its the Water Watcher?', '2004-05-28 16:01:11.000000', NULL, 1),
(740928, 78504, 22332, '<td valign="top">Nice angle!  It realy makes the picture.  Only one problem...  It''s not a Pepsi bottle! :)</td>', 'Nice angle!  It realy makes the picture.  Only one problem...  It''s not a Pepsi bottle! :)', '2004-05-28 16:02:10.000000', NULL, 1),
