(740930, 79007, 22332, '<td valign="top">Wow!  Uh... what is it?  Very cool looking, whatever it is!  Nice colors</td>', 'Wow!  Uh... what is it?  Very cool looking, whatever it is!  Nice colors', '2004-05-28 16:04:09.000000', NULL, 1),
(740933, 78435, 18374, '<td valign="top">Very nice shot!  I love the even lighting on the rims of the bowls and the reflections in the glass.  The color of the wine bothers me a little bit- it looks orange!?</td>', 'Very nice shot!  I love the even lighting on the rims of the bowls and the reflections in the glass.  The color of the wine bothers me a little bit- it looks orange!?', '2004-05-28 16:05:00.000000', NULL, 1),
(740934, 79191, 22332, '<td valign="top">Oh wow!  Cool one!  What is that thing in the lower half?  Regardless, I really like the "feel" of the lighting.  Way to go!</td>', 'Oh wow!  Cool one!  What is that thing in the lower half?  Regardless, I really like the "feel" of the lighting.  Way to go!', '2004-05-28 16:05:44.000000', NULL, 1),
(740935, 79089, 14477, '<td valign="top">I would have liked this picture even better if we couldn''t see a blanket at the baby''s feet.  I love the shot though!!!</td>', 'I would have liked this picture even better if we couldn''t see a blanket at the baby''s feet.  I love the shot though!!!', '2004-05-28 16:05:52.000000', NULL, 1),
