(741349, 78426, 20395, '<td valign="top">I like the tipped horizon line.  The black seems kinda light- twilight? It''s bleached out the red of the tailights some.</td>', 'I like the tipped horizon line.  The black seems kinda light- twilight? It''s bleached out the red of the tailights some.', '2004-05-29 01:22:33.000000', NULL, 1),
(741351, 79313, 20395, '<td valign="top">You might try a black background next time- the backyard is distracting.</td>', 'You might try a black background next time- the backyard is distracting.', '2004-05-29 01:23:37.000000', NULL, 1),
