(741365, 79088, 21245, '<td valign="top">That''s a lot of lights alright.  I love the exposure allowing the streaking street lights.</td>', 'That''s a lot of lights alright.  I love the exposure allowing the streaking street lights.', '2004-05-29 01:39:29.000000', NULL, 1),
(741366, 79071, 21245, '<td valign="top">I love those fibre lights.  Great shot!</td>', 'I love those fibre lights.  Great shot!', '2004-05-29 01:40:17.000000', NULL, 1),
