(741559, 79088, 20685, '<td valign="top">nice angle but were you using a tripod as it seems blurred in areas?</td>', 'nice angle but were you using a tripod as it seems blurred in areas?', '2004-05-29 07:47:52.000000', NULL, 1),
(741562, 79089, 20685, '<td valign="top">what a great moment to capture and sooo well too. Doesn''t quite fit the challange for me so had to knock off a point.</td>', 'what a great moment to capture and sooo well too. Doesn''t quite fit the challange for me so had to knock off a point.', '2004-05-29 07:50:30.000000', NULL, 1),
