INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(741668, 79177, 16982, '<td valign="top">A closer shot would have looked better in my opinion.</td>', 'A closer shot would have looked better in my opinion.', '2004-05-29 11:17:12.000000', NULL, 1),
(741674, 78426, 16982, '<td valign="top">Very colourful, and the angle you chose was very good.  Some parts of the sky could have done with being less overexposed.</td>', 'Very colourful, and the angle you chose was very good.  Some parts of the sky could have done with being less overexposed.', '2004-05-29 11:26:17.000000', NULL, 1),
(741675, 79262, 16004, '<td valign="top">this is a wonderful photograph, and i''m at a total loss as how you did it! the quality of this image is leagues ahead of many of the ones on offer this week - it''s seemingly simple but oh so well set up and executed.  my only slight thought is that there is a little too much empty space at the top...  but that aside, it''s perfect.  10.</td>', 'this is a wonderful photograph, and i''m at a total loss as how you did it! the quality of this image is leagues ahead of many of the ones on offer this week - it''s seemingly simple but oh so well set up and executed.  my only slight thought is that there is a little too much empty space at the top...  but that aside, it''s perfect.  10.', '2004-05-29 11:26:29.000000', NULL, 1),
(741680, 78050, 16982, '<td valign="top">I like the way the light part has a darker background, and vice versa.  Very good shot.</td>', 'I like the way the light part has a darker background, and vice versa.  Very good shot.', '2004-05-29 11:33:04.000000', NULL, 1),
(741686, 78882, 15029, '<td valign="top">The image seem s blue tinted and voer-exposed</td>', 'The image seem s blue tinted and voer-exposed', '2004-05-29 11:34:43.000000', NULL, 1),
(741688, 78512, 15029, '<td valign="top">very surreal. a very nice abstract</td>', 'very surreal. a very nice abstract', '2004-05-29 11:35:15.000000', NULL, 1),
(741690, 78297, 15029, '<td valign="top">I don''t see multiple light scources</td>', 'I don''t see multiple light scources', '2004-05-29 11:35:53.000000', NULL, 1),
(741691, 78275, 16982, '<td valign="top">An alternative interpretation of the challenge!  I see no reason why you shouldn''t be allowed to do this.  I hope you''re not voted down for it.</td>', 'An alternative interpretation of the challenge!  I see no reason why you shouldn''t be allowed to do this.  I hope you''re not voted down for it.', '2004-05-29 11:36:27.000000', NULL, 1),
(741692, 78375, 15029, '<td valign="top">great photo. nice soft focus. really nice shot</td>', 'great photo. nice soft focus. really nice shot', '2004-05-29 11:36:48.000000', NULL, 1),
