(742647, 79131, 10644, '<td valign="top">very creative</td>', 'very creative', '2004-05-30 16:11:16.000000', NULL, 1),
(742648, 79281, 19608, '<td valign="top">Great capture in low lighting.  May not need all of the very left side,  Adding the audience is a great touch that most shooters would probably avoid.</td>', 'Great capture in low lighting.  May not need all of the very left side,  Adding the audience is a great touch that most shooters would probably avoid.', '2004-05-30 16:11:37.000000', NULL, 1),
