(742651, 79037, 10644, '<td valign="top">definately meets the challenge</td>', 'definately meets the challenge', '2004-05-30 16:12:48.000000', NULL, 1),
(742653, 79264, 10644, '<td valign="top">love the shadow and light play</td>', 'love the shadow and light play', '2004-05-30 16:13:28.000000', NULL, 1),
(742654, 78251, 19608, '<td valign="top">Very graphic - a nice jdea well done.</td>', 'Very graphic - a nice jdea well done.', '2004-05-30 16:13:31.000000', NULL, 1),
