(742658, 78412, 10644, '<td valign="top">you certainly met the challenge</td>', 'you certainly met the challenge', '2004-05-30 16:15:06.000000', NULL, 1),
(742659, 79294, 10644, '<td valign="top">pretty and unusual</td>', 'pretty and unusual', '2004-05-30 16:15:29.000000', NULL, 1),
