(742661, 79099, 19608, '<td valign="top">Nice sky and even better reflections.  Composition with leading line from bottom using the canal is perfect.  Very well done - it should score high.</td>', 'Nice sky and even better reflections.  Composition with leading line from bottom using the canal is perfect.  Very well done - it should score high.', '2004-05-30 16:16:44.000000', NULL, 1),
(742662, 79279, 10644, '<td valign="top">like the lighting and shadows</td>', 'like the lighting and shadows', '2004-05-30 16:17:44.000000', NULL, 1),
