(742669, 79202, 19608, '<td valign="top">Interesting critters - look like cucumber slices.  Nice muted colors.</td>', 'Interesting critters - look like cucumber slices.  Nice muted colors.', '2004-05-30 16:20:45.000000', NULL, 1),
