(743066, 78742, 22286, '<td valign="top">I like the starkness of it.  And I love the pattern to the light.</td>', 'I like the starkness of it.  And I love the pattern to the light.', '2004-05-30 22:52:40.000000', NULL, 1),
(743077, 79215, 22286, '<td valign="top">Almost great.  I think it would be better if there were less sky (or more).  I don''t like the even split between sky and building.</td>', 'Almost great.  I think it would be better if there were less sky (or more).  I don''t like the even split between sky and building.', '2004-05-30 22:58:58.000000', NULL, 1),
