(744757, 78985, 10818, '<td valign="top">I am not in to tarot cards, but I do like the photo.  Very nice.</td>', 'I am not in to tarot cards, but I do like the photo.  Very nice.', '2004-05-31 23:38:02.000000', NULL, 1),
(744758, 78309, 18349, '<td valign="top">Very nice.  Could use this one for the deep DOF challenge! :o)</td>', 'Very nice.  Could use this one for the deep DOF challenge! :o)', '2004-05-31 23:38:25.000000', NULL, 1),
(744759, 79250, 18349, '<td valign="top">Pretty colors and interesting reflections.</td>', 'Pretty colors and interesting reflections.', '2004-05-31 23:38:48.000000', NULL, 1),
(744762, 78620, 18349, '<td valign="top">Very nice.  I like the red; it adds character and mood.</td>', 'Very nice.  I like the red; it adds character and mood.', '2004-05-31 23:39:07.000000', NULL, 1),
(744765, 78281, 18349, '<td valign="top">Looks other-worldly (in a good way).  :o)</td>', 'Looks other-worldly (in a good way).  :o)', '2004-05-31 23:39:33.000000', NULL, 1),
(744767, 79216, 18349, '<td valign="top">Looks like one of my recurring dreams. ;o)</td>', 'Looks like one of my recurring dreams. ;o)', '2004-05-31 23:39:56.000000', NULL, 1),
(744768, 78810, 18349, '<td valign="top">Very nice.  My only nitpick is that it seems tilted down to the right.  Maybe it''s me...maybe it''s the fact I''ve been voting and commenting for two hours.  :o)</td>', 'Very nice.  My only nitpick is that it seems tilted down to the right.  Maybe it''s me...maybe it''s the fact I''ve been voting and commenting for two hours.  :o)', '2004-05-31 23:40:37.000000', NULL, 1),
