(745697, 78494, 6130, '<td valign="top">Beautiful 10</td>', 'Beautiful 10', '2004-06-01 17:36:48.000000', NULL, 1),
(745698, 77987, 16004, '<td valign="top">it''s a nice looking pub, but the shot is quite a bit of focus, which might affect your overall score - sharp images do usually tend to do better here.  to get round this, when you''re out and about it might be worth keepin an eye out for a flat surface you can balance your camera on - taking a shot at night / dusk invariably leads to a longer exposure time, and hand shake is impossible to avoid.  using a timer (if it has one) and a flat surface so you don''t have to hold the camera can result in some really sharp photos.</td>', 'it''s a nice looking pub, but the shot is quite a bit of focus, which might affect your overall score - sharp images do usually tend to do better here.  to get round this, when you''re out and about it might be worth keepin an eye out for a flat surface you can balance your camera on - taking a shot at night / dusk invariably leads to a longer exposure time, and hand shake is impossible to avoid.  using a timer (if it has one) and a flat surface so you don''t have to hold the camera can result in some really sharp photos.', '2004-06-01 17:36:50.000000', NULL, 1),
(745700, 79239, 6130, '<td valign="top">Funny and very good.</td>', 'Funny and very good.', '2004-06-01 17:37:37.000000', NULL, 1),
(745702, 78994, 6130, '<td valign="top">So beautiful .</td>', 'So beautiful .', '2004-06-01 17:38:01.000000', NULL, 1),
(745705, 79158, 16004, '<td valign="top">this is a lovely piece of illuminatory art.  the sepia tones, the whooshy whooshy light, and the way the edges of the raised bits glow (thereby conveying a three-dimensional appearance and gives a strong impression of feel) really appeals to me.  the shadow makes it a tiny bit unbalanced in terms of symmetry, but that aside i think that this is very well composed and taken photograph.  excellent - 9.</td>', 'this is a lovely piece of illuminatory art.  the sepia tones, the whooshy whooshy light, and the way the edges of the raised bits glow (thereby conveying a three-dimensional appearance and gives a strong impression of feel) really appeals to me.  the shadow makes it a tiny bit unbalanced in terms of symmetry, but that aside i think that this is very well composed and taken photograph.  excellent - 9.', '2004-06-01 17:40:26.000000', NULL, 1),
(745713, 79231, 16004, '<td valign="top">this is very nice - wine glasses are hardly original, i admit, but the addition of bubbles is sheer brilliance.  i can clearly see that the piece has been illuminated from different sources, as per the requirements.  i''m in two minds about the inclusion of the straw, because even though it affects the overall simplicity of the image, i do think it really ought to be there.  the lighting and greens are very good...  it''s a shame that spot editting isn''t allowed, because there''s a slightly distracting splodge on the right...  and did you consider using neatimage et al?  the colours are striking, and overall this is a definite top 10 favourite of the week.  8.</td>', 'this is very nice - wine glasses are hardly original, i admit, but the addition of bubbles is sheer brilliance.  i can clearly see that the piece has been illuminated from different sources, as per the requirements.  i''m in two minds about the inclusion of the straw, because even though it affects the overall simplicity of the image, i do think it really ought to be there.  the lighting and greens are very good...  it''s a shame that spot editting isn''t allowed, because there''s a slightly distracting splodge on the right...  and did you consider using neatimage et al?  the colours are striking, and overall this is a definite top 10 favourite of the week.  8.', '2004-06-01 17:46:09.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(745719, 79311, 16004, '<td valign="top">hmmm.  by rights, a curled up bit of white paper (looks like one side of bouble sided sticky tape) on a white background shouldn''t be interesting.  but it is!  striking even!  the different shades of greys are quite a draw, and i find myself staring at this...  all the little nuances rock!  i like a bit of minimalism, and by jove, i think this is it!  the off centre position is totally right, and there''s no way i''d alter this.  good job matey!  9.</td>', 'hmmm.  by rights, a curled up bit of white paper (looks like one side of bouble sided sticky tape) on a white background shouldn''t be interesting.  but it is!  striking even!  the different shades of greys are quite a draw, and i find myself staring at this...  all the little nuances rock!  i like a bit of minimalism, and by jove, i think this is it!  the off centre position is totally right, and there''s no way i''d alter this.  good job matey!  9.', '2004-06-01 17:50:09.000000', NULL, 1),
(745722, 79317, 12160, '<td valign="top">nice lighting and colors, framing is good too. focus is a bit soft for me. 6</td>', 'nice lighting and colors, framing is good too. focus is a bit soft for me. 6', '2004-06-01 17:51:59.000000', NULL, 1),
(745729, 78464, 16004, '<td valign="top">this is a very high quality image - and is also a very cherished trumpet.  this is a good subject for reflecting various sources of light, and you''ve certainly done it justice.  only slight reservation is the green felt - a bit too bright and a distraction.  if the instrument were turned a bit it might not be so apparent.  but seriously, that''s the only thing:  the background is perfectly subtle, the 45° angle is perfectly, erm, angled...  the left seems marginally out of focus compared to the rest though, but that''s being unnecessarily picky.  excellent.  8.</td>', 'this is a very high quality image - and is also a very cherished trumpet.  this is a good subject for reflecting various sources of light, and you''ve certainly done it justice.  only slight reservation is the green felt - a bit too bright and a distraction.  if the instrument were turned a bit it might not be so apparent.  but seriously, that''s the only thing:  the background is perfectly subtle, the 45° angle is perfectly, erm, angled...  the left seems marginally out of focus compared to the rest though, but that''s being unnecessarily picky.  excellent.  8.', '2004-06-01 17:55:03.000000', NULL, 1),
(745739, 77789, 19780, '<td valign="top">I think the subject and the expression is worthy but the background and framing is distracting. A closer crop to eliminate whatever that is by the tree would be a great help but the green of the grass and the dappled light is actually quite nice. I''m not seeing evidence of other light sources - just the shadows from the sunlight.</td>', 'I think the subject and the expression is worthy but the background and framing is distracting. A closer crop to eliminate whatever that is by the tree would be a great help but the green of the grass and the dappled light is actually quite nice. I''m not seeing evidence of other light sources - just the shadows from the sunlight.', '2004-06-01 18:03:24.000000', NULL, 1),
(745740, 78407, 19780, '<td valign="top">Though there is a quiet simplicityat work here, the composition is ultimately a little bland. I don''t see any evidence of other light sources but I would like perhaps a little more context for the shot (some background or perhaps a more interesting angle with more detail on the surface of the wax).</td>', 'Though there is a quiet simplicityat work here, the composition is ultimately a little bland. I don''t see any evidence of other light sources but I would like perhaps a little more context for the shot (some background or perhaps a more interesting angle with more detail on the surface of the wax).', '2004-06-01 18:05:14.000000', NULL, 1),
(745747, 79020, 19780, '<td valign="top">I love the choice of using a traffic light as your source. Unfortunately the cripsness of the billiard balls is lost and the strange background of the blanket doesn''t do much to help your overall composition. I would suggest having more negative space to the right and perhaps spacing the balls (maybe only one ball per color) further away from the source. Your color exposure is great, Like the rich, saturated quality of the light.</td>', 'I love the choice of using a traffic light as your source. Unfortunately the cripsness of the billiard balls is lost and the strange background of the blanket doesn''t do much to help your overall composition. I would suggest having more negative space to the right and perhaps spacing the balls (maybe only one ball per color) further away from the source. Your color exposure is great, Like the rich, saturated quality of the light.', '2004-06-01 18:08:47.000000', NULL, 1),
(745775, 79306, 13602, '<td valign="top">this is beautiful, colors are magic in this shot, also verry good sharpness. 10</td>', 'this is beautiful, colors are magic in this shot, also verry good sharpness. 10', '2004-06-01 18:33:59.000000', NULL, 1),
(745789, 79240, 6130, '<td valign="top">I like this.</td>', 'I like this.', '2004-06-01 18:43:49.000000', NULL, 1),
(745826, 78255, 15920, '<td valign="top">This is almost perfectly lit.  I like the fact that there is reduced detail in the dark hat, yet there is some detail in the shirt.  I also like the reflections in the glass, as I think they really add some depth to the picture.  The detail on the paneling probably looks great on your wall, but just isn''t helping this otherwise great shot as it distracts from the subject.</td>', 'This is almost perfectly lit.  I like the fact that there is reduced detail in the dark hat, yet there is some detail in the shirt.  I also like the reflections in the glass, as I think they really add some depth to the picture.  The detail on the paneling probably looks great on your wall, but just isn''t helping this otherwise great shot as it distracts from the subject.', '2004-06-01 19:25:56.000000', NULL, 1),
(745832, 78375, 15920, '<td valign="top">Great idea to use the candles as fill light, as it really met the challenge  and the cancle light added to the mood.  The folds on the background distract a bit though, and could have been reduced by moving the curtain back from the subject.</td>', 'Great idea to use the candles as fill light, as it really met the challenge  and the cancle light added to the mood.  The folds on the background distract a bit though, and could have been reduced by moving the curtain back from the subject.', '2004-06-01 19:31:14.000000', NULL, 1),
(745838, 78264, 15920, '<td valign="top">Lighting could be improved a bit by being brighter and more directed at the "face".  The background is far enough away to be perfect, and this is cropped perfectly.</td>', 'Lighting could be improved a bit by being brighter and more directed at the "face".  The background is far enough away to be perfect, and this is cropped perfectly.', '2004-06-01 19:46:13.000000', NULL, 1),
(745839, 79262, 20330, '<td valign="top">I''d love to know how this was done. It looks like its a manipulated photo, but since its limited editing I guess it isnt. Beautiful colours.</td>', 'I''d love to know how this was done. It looks like its a manipulated photo, but since its limited editing I guess it isnt. Beautiful colours.', '2004-06-01 19:46:35.000000', NULL, 1),
(745841, 78435, 22423, '<td valign="top">How did you do that. I like it.</td>', 'How did you do that. I like it.', '2004-06-01 19:58:54.000000', NULL, 1),
(745842, 79011, 6130, '<td valign="top">Fantastic.</td>', 'Fantastic.', '2004-06-01 20:03:00.000000', NULL, 1),
(745844, 78386, 22423, '<td valign="top">I would like it better if the bottom right corner was cropped out, and just the top part of the flower was shown. Pretty flower, is it an orchid?</td>', 'I would like it better if the bottom right corner was cropped out, and just the top part of the flower was shown. Pretty flower, is it an orchid?', '2004-06-01 20:04:16.000000', NULL, 1),
(745846, 79239, 22423, '<td valign="top">The building to the left and the very bottom bothers me.</td>', 'The building to the left and the very bottom bothers me.', '2004-06-01 20:08:00.000000', NULL, 1),
(745851, 78464, 22423, '<td valign="top">i like it, but the backdrop looks odd.</td>', 'i like it, but the backdrop looks odd.', '2004-06-01 20:11:49.000000', NULL, 1),
(745852, 79216, 22423, '<td valign="top">Cool, how was it done?</td>', 'Cool, how was it done?', '2004-06-01 20:13:19.000000', NULL, 1),
(745853, 79161, 18349, '<td valign="top">The abstract nature of this image is acceptable, but I do not understand where the "focal point" of the image lies.  It is confusing to my eyes, and the blue lights serve to distract more than enhance the shot IMHO.</td>', 'The abstract nature of this image is acceptable, but I do not understand where the "focal point" of the image lies.  It is confusing to my eyes, and the blue lights serve to distract more than enhance the shot IMHO.', '2004-06-01 20:16:02.000000', NULL, 1),
(745854, 79156, 18349, '<td valign="top">The color scheme is nice, but the towel-as-a-backdrop is just not very attractive.  The candle is OOF, and the towel itself is not covering up all the back area you are trying to mask.  The black ceramic object is very distracting, as it does not fit i with the other colors.</td>', 'The color scheme is nice, but the towel-as-a-backdrop is just not very attractive.  The candle is OOF, and the towel itself is not covering up all the back area you are trying to mask.  The black ceramic object is very distracting, as it does not fit i with the other colors.', '2004-06-01 20:18:12.000000', NULL, 1),
(745855, 78683, 22423, '<td valign="top">interesting</td>', 'interesting', '2004-06-01 20:19:03.000000', NULL, 1),
